using System;using System.IO;using System.Collections.Generic;using LastRail.Battle;using Newtonsoft.Json.Linq;using NUnit.Framework;
namespace LastRail.Tests.EditMode { public class BCombatContractConsumerTests {
 static JObject Fixture()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261002/ContractConsumer/server-traces.json"));
 static JObject Case(int i)=>(JObject)Fixture()["cases"][i];
 static BCombatPlacementReplica Read(JObject c)=>new BCombatPlacementReplica((JObject)c["response"],(JObject)c["source"],"LOCAL_B_AUDIT");
 [Test] public void ActualRulePortOutputKeepsUnboundAndRepeatedCatalogIds(){var c=Case(0);var r=Read(c);Assert.IsFalse(r.StartReady);Assert.IsTrue(JToken.DeepEquals(c["response"],r.Capture()));var copy=r.Capture();copy["startReady"]=true;Assert.IsFalse(r.StartReady);Assert.IsTrue(JToken.DeepEquals(c["response"],r.Capture()));}
 [Test] public void ExplicitActualInstanceIdsAreRequiredForLocalFormation(){var r=Read(Case(0));Assert.Throws<ArgumentException>(()=>r.BuildLocalTestFormation("train",BCombatMode.Solo,new Dictionary<int,string>{{0,"same"},{1,"same"}}));var f=r.BuildLocalTestFormation("train",BCombatMode.Solo,new Dictionary<int,string>{{0,"actual-front"},{1,"actual-rear"}});Assert.AreEqual("actual-front",f.Slots[0].CarriageId);Assert.AreEqual("op_eve",f.Slots[0].OperatorId);Assert.IsTrue(f.Slots[1].IsCargo);}
 [TestCase(1)][TestCase(2)][TestCase(3)][TestCase(4)][TestCase(5)][TestCase(6)][TestCase(7)]
 public void ActualRulePortErrorsKeepExactDomainStatus(int i){var c=Case(i);var e=new BCombatRuleError((JObject)c["error"]);Assert.AreEqual((int)c["error"]["status"],e.Status);Assert.AreEqual((string)c["error"]["errorCode"],e.Code);}
 [Test] public void FrozenSupplierCapacityGapCannotBecomeApprovedSixSlotDeployment(){var c=Case(8);Assert.IsNotNull(c["response"],"Frozen original rule port exposes the capacity gap");Assert.Throws<ArgumentException>(()=>Read(c));}
 [TestCase("version")][TestCase("owner")][TestCase("ready")][TestCase("source")][TestCase("unbound")][TestCase("turret")][TestCase("duplicate")][TestCase("foreign")][TestCase("extra")]
 public void BadReadDoesNotAlterOriginalSource(string bad){var c=Case(0);var original=c.ToString();var response=(JObject)c["response"].DeepClone();switch(bad){case "version":response["version"]="A";break;case "owner":response["accountId"]="foreign";break;case "ready":response["startReady"]=true;break;case "source":response["placements"][0]["carriageId"]="foreign";break;case "unbound":response["unbound"]=new JArray();break;case "turret":((JArray)response["mountedTurrets"]).Add("attached");break;case "duplicate":response["placements"][1]["slot"]=0;break;case "foreign":response["placements"][0]["occupant"]["operatorId"]="op_kyle";break;case "extra":response["hp"]=10;break;}Assert.Throws<ArgumentException>(()=>new BCombatPlacementReplica(response,(JObject)c["source"],"LOCAL_B_AUDIT"));Assert.AreEqual(original,c.ToString());}
 [TestCase(0)][TestCase(1)][TestCase(2)][TestCase(3)][TestCase(4)][TestCase(5)][TestCase(6)][TestCase(7)]
 public void ActualVersionBoundaryClassifiesWithoutGrantingStartOrHistoricalRestore(int i){var b=Fixture()["boundary"][i];if(b["error"]!=null){var error=new BCombatRuleError((JObject)b["error"]);Assert.AreEqual(409,error.Status);return;}var r=new BCombatPolicyClassification((JObject)b["request"],(JObject)b["response"]);Assert.IsFalse(r.StartReady);Assert.IsFalse(r.AuthorizesHistoricalRestore);Assert.IsTrue(JToken.DeepEquals(b["response"],r.Capture()));}
 [Test] public void HistoricalUnknownCannotBeRelabeledAsNewB(){var request=new JObject{["purpose"]="NEW_B",["snapshotPolicyVersion"]="unknown"};var response=new JObject{["classification"]="HISTORICAL_PINNED",["policyVersion"]="unknown",["startReady"]=false};Assert.Throws<ArgumentException>(()=>new BCombatPolicyClassification(request,response));}
 [TestCase(false)][TestCase(true)] public void InvalidAccountTypeOrLengthCannotPassSourceComparison(bool tooLong){var c=Case(0);var response=(JObject)c["response"];var source=(JObject)c["source"];var id=tooLong?(JToken)new JValue(new string('x',129)):new JValue(123);response["accountId"]=id.DeepClone();source["accountId"]=id.DeepClone();Assert.Throws<ArgumentException>(()=>new BCombatPlacementReplica(response,source,tooLong?new string('x',129):"123"));}
 [Test] public void NumericResponsePolicyCannotMasqueradeAsStringOriginal(){Assert.Throws<ArgumentException>(()=>new BCombatPolicyClassification(new JObject{["purpose"]="RESTORE",["snapshotPolicyVersion"]="123"},new JObject{["classification"]="HISTORICAL_PINNED",["policyVersion"]=123,["startReady"]=false}));}
 [Test] public void UnsupportedErrorCannotSilentlyBecomeReady(){Assert.Throws<ArgumentException>(()=>new BCombatRuleError(new JObject{["status"]=200,["errorCode"]="combat_b_version_conflict"}));}
 }}
#endif
